script:
frappe.ready(() => {
  console.log('Audit Dashboard Loading...');
  refresh_stats();
});

function refresh_stats() {
  frappe.call({
    method: 'audit_management.audit_management.dashboard.get_dashboard_stats',
    callback: (r) => {
      console.log('Stats Response:', r.message);
      if (r.message) {
        document.getElementById('stat-pending').innerText = r.message.pending_for_me;
        document.getElementById('stat-high').innerText = r.message.high_risk;
        document.getElementById('stat-tat').innerText = r.message.tat_breached;
      }
    }
  });
}

style:
.audit-dashboard { padding: 15px; background: #f9f9f9; border-radius: 10px; border: 1px solid #eee; }
.section-title { font-size: 16px; font-weight: bold; margin: 15px 0 10px; color: #444; border-left: 4px solid #6f42c1; padding-left: 10px; }
.btn-group { display: flex; gap: 10px; margin-bottom: 20px; }
.btn-main { background: #6f42c1; color: white; padding: 10px 20px; border-radius: 5px; border: none; cursor: pointer; font-weight: bold; }
.btn-sub { background: white; color: #333; padding: 10px 15px; border-radius: 5px; border: 1px solid #ccc; cursor: pointer; }
.stats-row { display: flex; gap: 15px; }
.stat-box { flex: 1; padding: 20px; border-radius: 8px; text-align: center; color: white; }
.stat-box.blue { background: #3498db; }
.stat-box.red { background: #e74c3c; }
.stat-box.orange { background: #f39c12; }
.stat-box .val { display: block; font-size: 28px; font-weight: bold; }
.stat-box .lbl { font-size: 12px; text-transform: uppercase; }
